    float segM(float i, float n) {
        if (int(amzp_mirrorMode) == 0) return seg(i, n);
        if (i < 0.0 || i >= n) return 0.0;
        float m = abs(2.0 * (i + 0.5) / n - 1.0);
        if (int(amzp_mirrorMode) == 2) m = 1.0 - m;
        return seg(clamp(floor(m * n), 0.0, n - 1.0), n);
    }
    float sdBox(float2 p, float2 b) {
        float2 d = abs(p) - b;
        return length(max(d, 0.0)) + min(max(d.x, d.y), 0.0);
    }
    float ecgW(float t) {
        t = fract(t);
        float P = (t - 0.18) / 0.035, Q = (t - 0.30) / 0.012, Rr = (t - 0.33) / 0.014, S = (t - 0.365) / 0.014, Tw = (t - 0.58) / 0.05;
        return 0.12 * exp(-P * P) - 0.15 * exp(-Q * Q) + exp(-Rr * Rr) - 0.3 * exp(-S * S) + 0.25 * exp(-Tw * Tw);
    }
    float3 hue2rgb(float h) { return clamp(abs(mod(h * 6.0 + float3(0.0, 4.0, 2.0), 6.0) - 3.0) - 1.0, 0.0, 1.0); }
    float3 turnHue(float3 c, float deg) {
        float a = radians(deg), cs = cos(a), sn = sin(a);
        float3 k = float3(0.57735);
        return c * cs + cross(k, c) * sn + k * dot(k, c) * (1.0 - cs);
    }
    float waveAt(float x, float n, bool alt) {
        float i1 = floor(x);
        float f = x - i1;
        float a0 = segM(i1 - 1.0, n), a1 = segM(i1, n), a2 = segM(i1 + 1.0, n), a3 = segM(i1 + 2.0, n);
        if (alt) {
            float s1 = mod(i1, 2.0) < 0.5 ? 1.0 : -1.0;
            a0 *= -s1; a1 *= s1; a2 *= -s1; a3 *= s1;
        }
        return 0.5 * ((2.0 * a1) + (-a0 + a2) * f + (2.0 * a0 - 5.0 * a1 + 4.0 * a2 - a3) * f * f + (-a0 + 3.0 * a1 - 3.0 * a2 + a3) * f * f * f);
    }
    void amzRender() {
        float4 lay = amzTexture(0, amzScreenNorm());
        float asp = layer.x / max(layer.y, 1.0);
        float2 lp = (amzLayerNorm() - 0.5) * layer;
        lp = nmStd(float2(lp.x, -lp.y), 1.0);
        float2 ln = float2(lp.x, -lp.y) / max(layer, float2(1.0)) + 0.5;
        float2 p = float2(ln.x * asp, 1.0 - ln.y);
        float scrH = layer.y * screen.zw.y / max(screen.zw.y, 1.0);
        float onePx = 1.0 / max(scrH, 1.0);
        float px1080 = screen.zw.y / 1080.0 / max(layer.y, 1.0);
        float n = max(floor(amzp_segCount + 0.5), 1.0);
        float lv = int(amzp_beatSrc) == 1 ? amzp_bass : (int(amzp_beatSrc) == 2 ? amzp_mid : (int(amzp_beatSrc) == 3 ? amzp_high : amzp_audioLevel));
