        float tClk = time + amzp_audio_level * amzp_beatRush;
        float sizeF = 1.0 + amzp_sizePunch * drive;
        float glowF = 1.0 + amzp_glowPunch * drive;
        float brightF = 1.0 + amzp_brightPunch * drive;
        float2 A = float2(amzp_fromX * asp, amzp_fromY), B = float2(amzp_toX * asp, amzp_toY);
