            float2 d = B - A;
            float L = max(length(d), 1e-5);
            float2 dir = d / L;
            float2 r = p - A;
            u = dot(r, dir) / L;
            v = dot(r, float2(dir.y, -dir.x));
            len = L;
        } else {
            float2 r = p - A;
            float rr = length(r), r0 = max(length(B - A) + amzp_pushDist * px1080 * drive, 1e-5);
            float arc = clamp(amzp_ringArc, 0.05, 1.0);
            u = fract((atan(r.y, r.x) - atan(B.y - A.y, B.x - A.x) - radians(amzp_ringSpin * tClk)) / 6.2831853) / arc;
            v = rr - r0;
            len = 6.2831853 * max(rr, 1e-5) * arc;
