        float x = u * len;
        float fi = floor(u * n);
        float d = 1e5;
        float fillA = 0.0;
        if (int(amzp_vizStyle) == 0) {
            bool both = int(amzp_growDir) == 2;
            float sv = both ? v : vd;
            float xs = u * n - 0.5;
            float env = pow(sin(3.14159265 * clamp(u, 0.0, 1.0)), 0.8);
            float y = waveAt(xs, n, both) * H * env;
            float e = 0.02;
            float envA = pow(sin(3.14159265 * clamp(u + e / n, 0.0, 1.0)), 0.8);
            float envB = pow(sin(3.14159265 * clamp(u - e / n, 0.0, 1.0)), 0.8);
            float ya = waveAt(xs + e, n, both) * H * envA, yb = waveAt(xs - e, n, both) * H * envB;
            float slope = (ya - yb) / max(2.0 * e * step0, 1e-6);
            d = abs(sv - y) / sqrt(1.0 + slope * slope) - hw;
            if (u < 0.0 || u > 1.0) d = abs(sv) - hw;
            if ((amzp_ring>0.5)) d = abs(sv - y) / sqrt(1.0 + slope * slope) - hw;
            if ((amzp_ring>0.5) && amzp_ringArc < 0.999 && u > 1.0) d = 1e5;
        } else if (int(amzp_vizStyle) == 1) {
            float bl = 0.5 * max(amzp_barLen, 0.001);
