                if (int(amzp_growDir) == 1) c = -c;
                d = min(d, sdBox(float2(x - (i + 0.5) * step0, v - c), float2(hw, bl)));
            }
        } else if (int(amzp_vizStyle) == 2) {
            for (int k = -1; k <= 1; k++) {
                float i = fi + float(k);
