            float ya = max(waveAt(xs + e, n, false), 0.0) * H * pow(sin(3.14159265 * clamp(u + e / n, 0.0, 1.0)), 0.8);
            float yb = max(waveAt(xs - e, n, false), 0.0) * H * pow(sin(3.14159265 * clamp(u - e / n, 0.0, 1.0)), 0.8);
            float slope = (ya - yb) / max(2.0 * e * step0, 1e-6);
