            d = abs(sv - y) / sqrt(1.0 + slope * slope) - hw;
            if (int(amzp_growDir) != 2) d = min(d, abs(vd) - hw);
            if (u < 0.0 || u > 1.0) d = (amzp_ring>0.5) ? 1e5 : abs(v) - hw;
