        } else if (int(amzp_vizStyle) == 7) {
            for (int k = -1; k <= 1; k++) {
                float i = fi + float(k);
                if (i < 0.0 || i >= n) continue;
                float pw = 1.0 - clamp(amzp_pyrTaper, 0.0, 1.0) * abs(2.0 * (i + 0.5) / n - 1.0);
                float h2 = 0.5 * max(segM(i, n) * H * pw, 0.0005);
                d = min(d, sdBox(float2(x - (i + 0.5) * step0, vd - h2), float2(hw, h2)));
