            float bh = max(amzp_blockH * px1080, onePx), cell = bh + max(amzp_blockGap * px1080, 0.0);
            for (int k = -1; k <= 1; k++) {
                float i = fi + float(k);
                if (i < 0.0 || i >= n) continue;
                float nb = max(floor(segM(i, n) * H / cell + 0.5), 1.0);
                float c = clamp(floor(vd / cell), 0.0, nb - 1.0);
                d = min(d, sdBox(float2(x - (i + 0.5) * step0, vd - (c * cell + 0.5 * bh)), float2(hw, 0.5 * bh)));
            }
        } else if (int(amzp_vizStyle) == 10) {
            float sv = int(amzp_growDir) == 1 ? -v : v;
            float amp = H * (0.2 + 0.8 * clamp(waveAt(u * n - 0.5, n, false), 0.0, 1.0));
            float bl = len / max(amzp_ecgBeats, 0.01);
            float wd = max(hw * 2.0 + soft, bl * 0.03);
            float ph0 = -tClk * amzp_ecgSpeed;
            float2 q0 = float2(-wd, ecgW((x - wd) / bl + ph0) * amp - sv);
            float dm = 1e5;
            for (int k = 1; k <= 24; k++) {
                float ox = -wd + 2.0 * wd * float(k) / 24.0;
                float2 q1 = float2(ox, ecgW((x + ox) / bl + ph0) * amp - sv);
                float2 ab = q1 - q0;
                float tq = clamp(dot(-q0, ab) / max(dot(ab, ab), 1e-12), 0.0, 1.0);
                dm = min(dm, length(q0 + ab * tq));
                q0 = q1;
            }
            d = dm - hw;
            if (u < 0.0 || u > 1.0) d = (amzp_ring>0.5) ? 1e5 : abs(v) - hw;
        } else {
            for (int k = -1; k <= 1; k++) {
                float i = fi + float(k);
                if (i < 0.0 || i >= n) continue;
                d = min(d, length(float2(x - (i + 0.5) * step0, vd - segM(i, n) * H)) - hw);
            }
        }
        float cov = 1.0 - smoothstep(-0.5 * soft, 0.5 * soft, d);
        float gs = max(amzp_glowSize * px1080, 1e-5);
