        if (int(amzp_colorMode) == 0) col = amzp_baseCol.rgb;
        else if (int(amzp_colorMode) == 1) col = mix(amzp_baseCol.rgb, amzp_peakCol.rgb, rp);
        else if (int(amzp_colorMode) == 2) col = mix(amzp_baseCol.rgb, amzp_peakCol.rgb, 0.5 + 0.5 * sin(6.2831853 * (tClk * amzp_hueSpeed - clamp(u, 0.0, 1.0))));
