        col *= brightF;
        float4 ink = float4(clamp(col, 0.0, 1.0), 1.0) * a;
        ink += float4(amzp_bgCol.rgb * amzp_bgCol.a, amzp_bgCol.a) * (1.0 - ink.a);
        amzOutput = nmBlend(lay, ink);
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
